344			text := strings.TrimSpace(typed)
345			if text == "" {
346				return 0, false
347			}
348			if duration, err := time.ParseDuration(text); err == nil {
349				return duration, true
350			}
351			if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
352				return time.Duration(number * float64(time.Second)), true
353			}
354		}
355		return 0, false
