836	// handleDiscover implements the weighted discovery entry: only explicitly
837	// healthy instances whose last heartbeat is not strictly past the lost
838	// boundary are returned. An instance exactly on the boundary is still
839	// online. Records strictly past the boundary are removed by the lost
840	// cleanup in a single transaction, so a storage failure leaves every
841	// record unchanged and yields no candidate list; online and
842	// unhealthy-but-fresh records are never touched.
843	func (s *Server) handleDiscover(c *gin.Context) {
844		bag, apiErr := buildParamBag(c)
845		if apiErr != nil {
846			writeError(c, apiErr)
847			return
848		}
849		serviceName, apiErr := bag.locateText("serviceName", serviceNameKeys, "service_name must not be empty")
850		if apiErr != nil {
851			writeError(c, apiErr)
852			return
853		}
854		evaluateValue, ok := bag.get(evaluateAtKeys)
855		if !ok {
856			writeError(c, errInvalidParameter("evaluate_at is required"))
857			return
858		}
859		evaluateAt, ok := parseTimeValue(evaluateValue)
860		if !ok {
861			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
862			return
863		}
864		timeoutValue, ok := bag.get(timeoutKeys)
865		if !ok {
866			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
867			return
868		}
869		timeout, ok := parseTimeout(timeoutValue)
870		if !ok || timeout <= 0 {
871			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
872			return
873		}
874	
875		instances, err := s.store.ListInstances(serviceName)
876		if err != nil {
877			writeError(c, errStorageUnavailable())
878			return
879		}
880		for _, instance := range instances {
881			if evaluateAt.Before(instance.HeartbeatAt) {
882				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
883				return
884			}
885		}
886		candidates := make([]gin.H, 0, len(instances))
887		lostKeys := make([]store.InstanceKey, 0)
888		for _, instance := range instances {
889			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
890				lostKeys = append(lostKeys, store.InstanceKey{
891					ServiceName: instance.ServiceName,
892					InstanceID:  instance.InstanceID,
893				})
894				continue
895			}
896			if !instance.Healthy {
897				continue
898			}
899			candidates = append(candidates, instanceJSON(instance))
900		}
901		// Lost cleanup deletes records strictly past the timeout. It runs only
902		// after the request is fully validated, and all lost records are removed
903		// in one transaction: a storage failure rolls everything back, so a
904		// failed request never leaves partial deletions behind.
905		if len(lostKeys) > 0 {
906			if err := s.store.DeleteInstances(lostKeys); err != nil {
907				writeError(c, errStorageUnavailable())
908				return
909			}
910		}
911		sortDiscoverHits(candidates)
912		c.JSON(200, gin.H{
913			"service_name":      serviceName,
914			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
915			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
916			"instances":         candidates,
917		})
918	}
